func (msg HelloMessage) toBrokerMessage() (extensions.BrokerMessage, error) {
	// TODO: implement checks on message
	// Make sure the CloudEvents envelope is valid before sending
	if verr := msg.Validate(); verr != nil {
		return extensions.BrokerMessage{}, verr
	}

	// Attach the payload as CloudEvents event data
	if err := msg.SetData(event.ApplicationJSON, msg.Payload); err != nil {
		return extensions.BrokerMessage{}, err
	}

	// Marshal the whole CloudEvents envelope to the broker payload
	payload, err := json.Marshal(msg.Event)
	if err != nil {
		return extensions.BrokerMessage{}, err
	}

	// There is no headers here
	headers := make(map[string][]byte, 0)

	return extensions.BrokerMessage{
		Headers: headers,
		Payload: payload,
	}, nil
}

// CorrelationID will give the correlation ID of the message, based on AsyncAPI spec
func (msg HelloMessage) CorrelationID() string {
	if msg.Payload.Correlationid != nil {
		return *msg.Payload.Correlationid
	}

	return ""
}

// SetCorrelationID will set the correlation ID of the message, based on AsyncAPI spec
